@testable import RFC_1950
import Byte
import Testing

@Suite
struct `zlib interoperability` {
    private static func bytes(_ values: [UInt8]) -> [Byte] { values.map { Byte($0) } }
    private static let text: [Byte] = bytes(Array(repeating: Array("The quick brown fox jumps over the lazy dog. ".utf8), count: 8).flatMap { $0 })

    @Test(arguments: [[0x78, 0x01, 0x0B, 0xC9, 0x48, 0x55, 0x28, 0x2C, 0xCD, 0x4C, 0xCE, 0x56, 0x48, 0x2A, 0xCA, 0x2F, 0xCF, 0x53, 0x48, 0xCB, 0xAF, 0x50, 0xC8, 0x2A, 0xCD, 0x2D, 0x28, 0x56, 0xC8, 0x2F, 0x4B, 0x2D, 0x52, 0x28, 0x01, 0x4A, 0xE7, 0x24, 0x56, 0x55, 0x2A, 0xA4, 0xE4, 0xA7, 0xEB, 0x29, 0x84, 0x8C, 0x2A, 0x26, 0x37, 0x34, 0x00, 0x65, 0x31, 0x81, 0x39], [0x78, 0x9C, 0x0B, 0xC9, 0x48, 0x55, 0x28, 0x2C, 0xCD, 0x4C, 0xCE, 0x56, 0x48, 0x2A, 0xCA, 0x2F, 0xCF, 0x53, 0x48, 0xCB, 0xAF, 0x50, 0xC8, 0x2A, 0xCD, 0x2D, 0x28, 0x56, 0xC8, 0x2F, 0x4B, 0x2D, 0x52, 0x28, 0x01, 0x4A, 0xE7, 0x24, 0x56, 0x55, 0x2A, 0xA4, 0xE4, 0xA7, 0xEB, 0x29, 0x84, 0x8C, 0x2A, 0x26, 0x57, 0x31, 0x00, 0x65, 0x31, 0x81, 0x39], [0x78, 0xDA, 0x0B, 0xC9, 0x48, 0x55, 0x28, 0x2C, 0xCD, 0x4C, 0xCE, 0x56, 0x48, 0x2A, 0xCA, 0x2F, 0xCF, 0x53, 0x48, 0xCB, 0xAF, 0x50, 0xC8, 0x2A, 0xCD, 0x2D, 0x28, 0x56, 0xC8, 0x2F, 0x4B, 0x2D, 0x52, 0x28, 0x01, 0x4A, 0xE7, 0x24, 0x56, 0x55, 0x2A, 0xA4, 0xE4, 0xA7, 0xEB, 0x29, 0x84, 0x8C, 0x2A, 0x26, 0x57, 0x31, 0x00, 0x65, 0x31, 0x81, 0x39]] as [[UInt8]])
    func `streams from zlib at every level decode`(_ stream: [UInt8]) throws {
        #expect(try RFC_1950.decompress(Self.bytes(stream)) == Self.text)
    }

    @Test
    func `a corrupted Adler-32 trailer is rejected`() {
        #expect(throws: RFC_1950.Error.self) { try RFC_1950.decompress(Self.bytes([0x78, 0x9C, 0x0B, 0xC9, 0x48, 0x55, 0x28, 0x2C, 0xCD, 0x4C, 0xCE, 0x56, 0x48, 0x2A, 0xCA, 0x2F, 0xCF, 0x53, 0x48, 0xCB, 0xAF, 0x50, 0xC8, 0x2A, 0xCD, 0x2D, 0x28, 0x56, 0xC8, 0x2F, 0x4B, 0x2D, 0x52, 0x28, 0x01, 0x4A, 0xE7, 0x24, 0x56, 0x55, 0x2A, 0xA4, 0xE4, 0xA7, 0xEB, 0x29, 0x84, 0x8C, 0x2A, 0x26, 0x57, 0x31, 0x00, 0x65, 0x31, 0x81, 0xC6])) }
    }

    @Test
    func `a corrupted header check is rejected`() {
        #expect(throws: RFC_1950.Error.invalidHeaderChecksum) { try RFC_1950.decompress(Self.bytes([0x78, 0x9D, 0x0B, 0xC9, 0x48, 0x55, 0x28, 0x2C, 0xCD, 0x4C, 0xCE, 0x56, 0x48, 0x2A, 0xCA, 0x2F, 0xCF, 0x53, 0x48, 0xCB, 0xAF, 0x50, 0xC8, 0x2A, 0xCD, 0x2D, 0x28, 0x56, 0xC8, 0x2F, 0x4B, 0x2D, 0x52, 0x28, 0x01, 0x4A, 0xE7, 0x24, 0x56, 0x55, 0x2A, 0xA4, 0xE4, 0xA7, 0xEB, 0x29, 0x84, 0x8C, 0x2A, 0x26, 0x57, 0x31, 0x00, 0x65, 0x31, 0x81, 0x39])) }
    }

    @Test
    func `a preset dictionary flag is rejected`() {
        #expect(throws: RFC_1950.Error.presetDictionaryRequired) { try RFC_1950.decompress(Self.bytes([0x78, 0xBB, 0x0B, 0xC9, 0x48, 0x55, 0x28, 0x2C, 0xCD, 0x4C, 0xCE, 0x56, 0x48, 0x2A, 0xCA, 0x2F, 0xCF, 0x53, 0x48, 0xCB, 0xAF, 0x50, 0xC8, 0x2A, 0xCD, 0x2D, 0x28, 0x56, 0xC8, 0x2F, 0x4B, 0x2D, 0x52, 0x28, 0x01, 0x4A, 0xE7, 0x24, 0x56, 0x55, 0x2A, 0xA4, 0xE4, 0xA7, 0xEB, 0x29, 0x84, 0x8C, 0x2A, 0x26, 0x57, 0x31, 0x00, 0x65, 0x31, 0x81, 0x39])) }
    }
}
